def build():
    s = (HERE / "index.html").read_text(encoding="utf-8")
    # применяем в порядке списка: длинные и контекстные ключи стоят раньше общих
    missing = []
    for ru, uz in T:
        if ru not in s:
            missing.append(ru)
        s = s.replace(ru, uz)
    (HERE / "uz.html").write_text(s, encoding="utf-8")
    left = [(i + 1, l.strip()[:160]) for i, l in enumerate(s.splitlines()) if re.search("[А-Яа-яЁё]", l)]
    print(f"не найдено ключей: {len(missing)}")
    for m in missing:
        print("  MISSING:", m[:90])
    print(f"строк с кириллицей: {len(left)}")
    for n, l in left:
        print(f"  {n}: {l}")

if __name__ == "__main__":
    build()
